const { formatPrice, formatQty } = require("../lib/format");
const { renderLine } = require("../src/ledger");
const assert = require("assert");
assert.strictEqual(formatPrice(12.5), "$12.50");
assert.strictEqual(formatPrice(0), "$0.00");
assert.strictEqual(formatPrice(7.999), "$8.00");
assert.strictEqual(formatQty(3), "3 units");
assert.strictEqual(formatPrice(-12.5), "-$12.50");
assert.strictEqual(formatPrice(-0.5), "-$0.50");
assert.strictEqual(renderLine("refund", -12.5), "refund: -$12.50");
console.log("format tests passed");
